CREATE TABLE t0 (c0 INTEGER, c3 INTEGER);
WITH cte0 AS (SELECT NULL AS c4 FROM t0 AS t1 LIMIT -1 OFFSET 1), cte1 AS (SELECT NULL FROM t0 AS t12), cte2 AS (SELECT NULL FROM t0 AS t15), cte3 AS (SELECT NULL FROM (SELECT NULL FROM t0 AS t24 LIMIT -1 OFFSET 1) AS subq1), cte4 AS (SELECT NULL FROM t0 AS t27), cte5 AS (SELECT NULL FROM (SELECT NULL FROM t0 AS t30) AS subq3 LIMIT -1 OFFSET 1), cte6 AS (SELECT CHANGES() AS c4 FROM t0 AS t32), cte7 AS (SELECT NULL FROM (SELECT NULL FROM t0 AS t34 LIMIT -1 OFFSET 1) AS subq5 LIMIT -1 OFFSET 1), cte8 AS (SELECT NULL AS c6 FROM (SELECT NULL FROM t0 AS t36) AS subq6), cte9 AS (SELECT NULL FROM t0 AS t39), cte10 AS (SELECT NULL FROM (SELECT NULL FROM t0 AS t40) AS subq7), cte11 AS (SELECT NULL FROM (SELECT NULL FROM t0 AS t46) AS subq8), cte12 AS (SELECT NULL FROM t0 AS t57 LIMIT -1 OFFSET 1) SELECT NULL FROM (SELECT TRUE AS c16, subq9.c10 AS c17 FROM (SELECT t59.c3 AS c4, t59.c3 AS c6, t59.c0 AS c10 FROM t0 AS t59 ORDER BY 1, c6 ASC, c4) AS subq9) AS subq10 WHERE subq10.c17 = CASE subq10.c16 WHEN 1 THEN subq10.c16 END ORDER BY 1